import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service.js';
import { TrackerWatchlistService } from '../tracker/tracker-watchlist.service.js';

/**
 * Actionable-recommendation state on alerts (intel_action_item). Owns the
 * memo↔alert link (so the Feed shows "memo drafted" + can reopen the Document
 * generated by apps/api) and curation items (talking points, weekly-report
 * flags). `intel_action_item` carries FORCE ROW LEVEL SECURITY
 * (`20260706010000_intel_full_rls_hold`) scoped to tenant_id; every query
 * additionally filters by tenantId (+ clientId) in app code, and — Gate J
 * (HP-06) — every alert-bearing write now proves the ALERT belongs to the
 * CLIENT too, via `TrackerWatchlistService.assertAlertInClient`. RLS alone
 * cannot catch a within-tenant, cross-client mismatch; only that predicate can.
 */
export interface AlertActionsSummary {
  memo?: {
    documentAttachmentId: string | null;
    title: string | null;
    /** MP-13/H-5: the memo's most recent hold, if any — lets the Feed deep-link "Review history". */
    reviewRequestId?: string | null;
  };
  inReport: boolean;
  talkingPoints: number;
}

/**
 * The docx fileName apps/api would produce for this alert's memo. Mirrors
 * alert-memo.service.ts's title precedence (PE code → bill display number → hearing
 * title → headline) and reuses its EXACT sanitization regex, applied to the whole
 * `${title}.docx` string, so a match here is a real match there.
 */
export function expectedMemoFileName(alert: {
  title: string;
  evidence: unknown;
}): string {
  const ev = (alert.evidence ?? {}) as {
    bill?: { displayNum?: string };
    hearing?: { title?: string | null };
    programElement?: { peCode?: string; title?: string | null };
    displayNum?: string;
  };
  const pe = ev.programElement;
  const subject = pe?.peCode
    ? `${pe.peCode}${pe.title ? ` — ${pe.title}` : ''}`
    : (ev.bill?.displayNum ?? ev.displayNum ?? ev.hearing?.title ?? alert.title);
  const title = `Client memo — ${subject}`.slice(0, 200);
  return `${title}.docx`.replace(/[\\/:*?"<>|]+/g, '-');
}

@Injectable()
export class ActionItemService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly watchlist: TrackerWatchlistService,
  ) {}

  /**
   * Record (or update) the memo↔alert link after apps/api generated + filed the memo.
   *
   * IDEMPOTENCY KEY: `(tenantId, alertId, kind:'memo')` — exactly one memo link per
   * alert. A retry (P1-14: the composer now offers "Link to alert" when the first
   * attempt failed) UPDATES `documentAttachmentId`/`title` in place and never inserts a
   * second row, so retrying is always safe.
   *
   * Not a Prisma `upsert`: that requires a unique index on those three columns, which
   * `intel_action_item` does not have — the DB carries a PARTIAL unique index instead
   * (`intel_action_item_alert_singleton_key` on `(alert_id, kind)` for
   * `kind IN ('memo','report','targeting_brief')`, `20260702160000`/`20260710050000`),
   * which Prisma's `upsert` cannot target. The update-then-create-if-absent below is
   * idempotent for the sequential-retry case this fixes; two *concurrent* first-writes
   * for the same alert both see `updated.count === 0` and both attempt `create` — the
   * loser now catches `P2002` (Gate J phase c, MP-05) and re-applies its data as an
   * update instead of 500ing, so neither caller's edit is silently dropped.
   *
   * Gate J (HP-06): `clientId` now joins EVERY predicate below, and
   * `assertAlertInClient` proves the alert belongs to this client before any write —
   * closing the gap where any caller in the tenant could overwrite another client's
   * memo link by URL-supplying a mismatched `clientId`.
   */
  async recordMemo(
    tenantId: string,
    clientId: string,
    alertId: string,
    userId: string,
    memo: { documentAttachmentId?: string | null; title?: string | null; content?: string | null },
  ) {
    await this.watchlist.assertClientInTenant(tenantId, clientId);
    await this.watchlist.assertAlertInClient(tenantId, clientId, alertId);
    const data = {
      documentAttachmentId: memo.documentAttachmentId ?? null,
      title: memo.title ?? null,
      // Gate H a-5: only touch `text` when the caller actually sent content —
      // NOT `?? null`. The reconcile-orphan-memo-links backfill (:254-260) and
      // any other caller that never had content to send must not overwrite a
      // real saved memo's text with null on an unrelated metadata update.
      ...(memo.content !== undefined ? { text: memo.content } : {}),
    };
    return this.prisma.withTenant(tenantId, async (tx) => {
      const updated = await tx.intelActionItem.updateMany({
        where: { tenantId, clientId, alertId, kind: 'memo' },
        data,
      });
      if (updated.count > 0) {
        return tx.intelActionItem.findFirst({ where: { tenantId, clientId, alertId, kind: 'memo' } });
      }
      try {
        return await tx.intelActionItem.create({
          data: { tenantId, clientId, alertId, kind: 'memo', createdBy: userId, ...data },
        });
      } catch (err) {
        // Gate J (MP-05) c-1/c-2: precedent is claim() (intel-alert.service.ts).
        // The other concurrent first-write already inserted between our
        // updateMany (count:0) and this create — re-run the update branch
        // against the now-existing row rather than 500ing.
        if ((err as { code?: string }).code !== 'P2002') throw err;
        await tx.intelActionItem.updateMany({
          where: { tenantId, clientId, alertId, kind: 'memo' },
          data,
        });
        return tx.intelActionItem.findFirst({ where: { tenantId, clientId, alertId, kind: 'memo' } });
      }
    });
  }

  /**
   * The memo link for an alert, if one exists (for "View memo" + reopen).
   * Gate J (HP-06/C-2): the controller used to bind the path `clientId` to `_`
   * and discard it, so this read the memo for ANY client's alert with that id.
   * Both proofs run before the read.
   */
  async getMemo(tenantId: string, clientId: string, alertId: string) {
    await this.watchlist.assertClientInTenant(tenantId, clientId);
    await this.watchlist.assertAlertInClient(tenantId, clientId, alertId);
    return this.prisma.withTenant(tenantId, (tx) =>
      tx.intelActionItem.findFirst({
        where: { tenantId, clientId, alertId, kind: 'memo' },
      }),
    );
  }

  /** Append a talking point (many allowed per alert). Gate J (HP-06): both
   *  ownership proofs run before the write — this route previously had neither. */
  async addTalkingPoint(
    tenantId: string,
    clientId: string,
    alertId: string,
    userId: string,
    text: string,
  ) {
    await this.watchlist.assertClientInTenant(tenantId, clientId);
    await this.watchlist.assertAlertInClient(tenantId, clientId, alertId);
    return this.prisma.withTenant(tenantId, (tx) =>
      tx.intelActionItem.create({
        data: {
          tenantId,
          clientId,
          alertId,
          kind: 'talking_point',
          text: text.slice(0, 2000),
          createdBy: userId,
        },
      }),
    );
  }

  /**
   * Toggle the weekly-report flag on an alert (idempotent). Gate J (HP-06):
   * both ownership proofs run before either branch, and `clientId` now joins
   * the delete/find predicates so a stale row from another client can never
   * be reached — mirrors `recordMemo`. Gate J (MP-05) c-1: two concurrent
   * `on=true` calls both see `!existing` and both `create` — the loser's
   * insert now catches `P2002` instead of 500ing. Unlike `recordMemo`, there
   * is no caller data to reconcile on conflict: a `report` row's only
   * meaning is its existence, and the winner's insert already satisfies
   * this call's goal (`inReport: true`), so the catch is a plain no-op.
   */
  async setReport(
    tenantId: string,
    clientId: string,
    alertId: string,
    userId: string,
    on: boolean,
  ) {
    await this.watchlist.assertClientInTenant(tenantId, clientId);
    await this.watchlist.assertAlertInClient(tenantId, clientId, alertId);
    if (!on) {
      await this.prisma.withTenant(tenantId, (tx) =>
        tx.intelActionItem.deleteMany({ where: { tenantId, clientId, alertId, kind: 'report' } }),
      );
      return { inReport: false };
    }
    await this.prisma.withTenant(tenantId, async (tx) => {
      const existing = await tx.intelActionItem.findFirst({
        where: { tenantId, clientId, alertId, kind: 'report' },
        select: { id: true },
      });
      if (!existing) {
        try {
          await tx.intelActionItem.create({
            data: { tenantId, clientId, alertId, kind: 'report', createdBy: userId },
          });
        } catch (err) {
          if ((err as { code?: string }).code !== 'P2002') throw err;
          // The other concurrent call already created the flag — exactly the
          // state this call wanted. Nothing left to do.
        }
      }
    });
    return { inReport: true };
  }

  /** List a client's curation items (talking points / report set), newest first. */
  async listForClient(tenantId: string, clientId: string, kind?: string) {
    return this.prisma.withTenant(tenantId, (tx) =>
      tx.intelActionItem.findMany({
        where: {
          tenantId,
          clientId,
          ...(kind ? { kind } : { kind: { in: ['talking_point', 'report'] } }),
        },
        orderBy: { createdAt: 'desc' },
        take: 200,
      }),
    );
  }

  /**
   * P1-14: DRY-RUN by default. Finds `intel_memo` attachments with no alert link and
   * re-creates the link where the alert can be identified UNAMBIGUOUSLY.
   *
   * Why this exists: filing the memo document and linking it to the alert are two
   * separate durable writes. The composer used to swallow a failure of the second one and
   * still say "drafted and filed", so a document could exist in the client's Documents
   * with no association — and reopening the composer generated a duplicate. The composer
   * now reports and retries (e-3..e-5); this verb cleans up rows stranded before that.
   *
   * Matching, in priority order:
   *  1. attachment metadata `alertId` — NOT AVAILABLE. `engagement_attachments` has no
   *     metadata/JSON column (id, tenant_id, client_id, meeting_id, mail_message_id,
   *     file_name, content_type, byte_size, bucket, s3_key, checksum_sha256, source,
   *     uploaded_by_user_id, indexed_at, created_at) and Gate C adds no migration, so
   *     e-6 is deliberately not done and this falls through to (2).
   *  2. exact `file_name` match against the memo title the alert WOULD produce, using the
   *     same sanitization alert-memo.service.ts applies.
   *  3. otherwise AMBIGUOUS — logged and skipped. Never guess.
   *
   * `engagement_attachments` is read with raw SQL because it lives in apps/api's Prisma
   * schema; intel-api has no model for it (same Aurora database, different schema file).
   * Reads only — the sole write is the intel_action_item link, under withTenant.
   */
  async reconcileOrphanMemoLinks(
    tenantId: string,
    opts: { apply: boolean },
    log: (msg: string) => void,
  ): Promise<{ candidates: number; linked: number; ambiguous: number }> {
    // 1. every memo document this tenant has filed.
    const attachments = await this.prisma.withTenant(tenantId, (tx) =>
      tx.$queryRaw<Array<{ id: string; client_id: string | null; file_name: string }>>`
        SELECT id::text AS id, client_id::text AS client_id, file_name
        FROM engagement_attachments
        WHERE tenant_id = ${tenantId}::uuid AND source = 'intel_memo'
        ORDER BY created_at DESC
        LIMIT 5000
      `,
    );
    if (!attachments.length) {
      log('RECONCILE_ORPHAN_MEMO_LINKS no intel_memo attachments for this tenant');
      return { candidates: 0, linked: 0, ambiguous: 0 };
    }

    // 2. which of them are already linked.
    const linkedIds = new Set(
      (
        await this.prisma.withTenant(tenantId, (tx) =>
          tx.intelActionItem.findMany({
            where: { tenantId, kind: 'memo', documentAttachmentId: { not: null } },
            select: { documentAttachmentId: true },
          }),
        )
      )
        .map((r) => r.documentAttachmentId)
        .filter((x): x is string => Boolean(x)),
    );
    const orphans = attachments.filter((a) => !linkedIds.has(a.id));
    if (!orphans.length) {
      log(
        `RECONCILE_ORPHAN_MEMO_LINKS all ${attachments.length} intel_memo attachment(s) already linked`,
      );
      return { candidates: 0, linked: 0, ambiguous: 0 };
    }

    // 3. build fileName → alertId(s) for this tenant's alerts. A fileName that maps to
    //    more than one alert is ambiguous by definition.
    const alerts = await this.prisma.withTenant(tenantId, (tx) =>
      tx.intelAlert.findMany({
        where: { tenantId },
        select: { id: true, clientId: true, title: true, evidence: true },
        orderBy: { createdAt: 'desc' },
        take: 20_000,
      }),
    );
    const byFileName = new Map<string, string[]>();
    for (const a of alerts) {
      const key = `${a.clientId}::${expectedMemoFileName(a)}`;
      byFileName.set(key, [...(byFileName.get(key) ?? []), a.id]);
    }

    let linked = 0;
    let ambiguous = 0;
    for (const att of orphans) {
      const matches = byFileName.get(`${att.client_id}::${att.file_name}`) ?? [];
      if (matches.length !== 1) {
        ambiguous += 1;
        log(
          `AMBIGUOUS attachment=${att.id} file="${att.file_name}" client=${att.client_id} ` +
            `candidateAlerts=${matches.length} — skipped`,
        );
        continue;
      }
      const alertId = matches[0]!;
      log(`MATCH attachment=${att.id} file="${att.file_name}" -> alert=${alertId}`);
      if (opts.apply) {
        await this.recordMemo(
          tenantId,
          att.client_id ?? '',
          alertId,
          'system:reconcile-orphan-memo-links',
          { documentAttachmentId: att.id, title: att.file_name.replace(/\.docx$/i, '') },
        );
        linked += 1;
      }
    }
    log(
      `RECONCILE_ORPHAN_MEMO_LINKS candidates=${orphans.length} linked=${linked} ` +
        `ambiguous=${ambiguous} mode=${opts.apply ? 'APPLY' : 'DRY_RUN'}`,
    );
    return { candidates: orphans.length, linked, ambiguous };
  }

  /** Batch action-state for a page of alerts (Feed decoration; no N+1). */
  async summaryForAlerts(
    tenantId: string,
    alertIds: string[],
  ): Promise<Map<string, AlertActionsSummary>> {
    const out = new Map<string, AlertActionsSummary>();
    if (!alertIds.length) return out;
    const rows = await this.prisma.withTenant(tenantId, (tx) =>
      tx.intelActionItem.findMany({
        where: { tenantId, alertId: { in: alertIds } },
        select: { alertId: true, kind: true, documentAttachmentId: true, title: true },
      }),
    );
    for (const id of alertIds) out.set(id, { inReport: false, talkingPoints: 0 });
    for (const r of rows) {
      const s = out.get(r.alertId) ?? { inReport: false, talkingPoints: 0 };
      if (r.kind === 'memo')
        s.memo = { documentAttachmentId: r.documentAttachmentId, title: r.title };
      else if (r.kind === 'report') s.inReport = true;
      else if (r.kind === 'talking_point') s.talkingPoints += 1;
      out.set(r.alertId, s);
    }

    // MP-13/H-5: attach the latest review_request id for alerts with a memo, so
    // the Feed's "Review history" button can deep-link to the specific request
    // instead of landing on the bare queue. review_request is apps/api-owned —
    // intel-api has no Prisma model for it, so this is a raw cross-schema read
    // (same pattern reconcileOrphanMemoLinks already uses for
    // engagement_attachments). Read-only: no migration needed.
    const memoAlertIds = [...out.entries()]
      .filter(([, s]) => s.memo)
      .map(([alertId]) => alertId);
    if (memoAlertIds.length) {
      const reviews = await this.prisma.withTenant(tenantId, (tx) =>
        tx.$queryRaw<Array<{ subject_id: string; id: string }>>`
          SELECT DISTINCT ON (subject_id) subject_id, id::text AS id
          FROM review_request
          WHERE tenant_id = ${tenantId}::uuid
            AND subject_type = 'alert'
            AND subject_id = ANY(${memoAlertIds}::text[])
          ORDER BY subject_id, created_at DESC
        `,
      );
      for (const row of reviews) {
        const s = out.get(row.subject_id);
        if (s?.memo) s.memo.reviewRequestId = row.id;
      }
    }
    return out;
  }
}
